import os
import math
import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Force HIP toolchain
os.environ.setdefault("CXX", "hipcc")

hip_src = r'''
#include <torch/extension.h>
#include <ATen/ATen.h>
#include <ATen/hip/HIPContext.h>
#include <hip/hip_runtime.h>

// Simple FlashAttention-style kernel for GQA, FP32 only, causal.
// Computes: out[b,h,q,d] = softmax_j<=q( (q·k)*scale ) @ v
// with implicit KV head sharing: kv_h = h / groups

__device__ __forceinline__ float shfl_down(float v, int delta) {
#if defined(__HIP_PLATFORM_AMD__)
    return __shfl_down(v, delta);
#else
    return __shfl_down(v, delta);
#endif
}

__device__ __forceinline__ float warp_reduce_sum(float v) {
    // AMD wavefront is 64, but __shfl_down works up to 64 lanes.
    for (int offset = 32; offset > 0; offset >>= 1) {
        v += shfl_down(v, offset);
    }
    return v;
}

__device__ __forceinline__ float warp_reduce_max(float v) {
    for (int offset = 32; offset > 0; offset >>= 1) {
        float other = shfl_down(v, offset);
        v = v > other ? v : other;
    }
    return v;
}

// Reduce across 128 threads as 2 wavefronts of 64.
__device__ __forceinline__ float block_reduce_sum_128(float v, float* shared) {
    int tid = (int)threadIdx.x;
    int lane = tid & 63;
    int warp = tid >> 6; // 0 or 1
    v = warp_reduce_sum(v);
    if (lane == 0) shared[warp] = v;
    __syncthreads();
    float out = 0.0f;
    if (warp == 0) {
        out = (lane < 2) ? shared[lane] : 0.0f;
        out = warp_reduce_sum(out);
    }
    __syncthreads();
    return shared[0];
}

__device__ __forceinline__ float block_reduce_max_128(float v, float* shared) {
    int tid = (int)threadIdx.x;
    int lane = tid & 63;
    int warp = tid >> 6;
    v = warp_reduce_max(v);
    if (lane == 0) shared[warp] = v;
    __syncthreads();
    float out = -INFINITY;
    if (warp == 0) {
        out = (lane < 2) ? shared[lane] : -INFINITY;
        out = warp_reduce_max(out);
    }
    __syncthreads();
    return shared[0];
}

__global__ void gqa_attn_fwd_fp32(
    const float* __restrict__ Q, // [B,H,S,D]
    const float* __restrict__ K, // [B,HKV,S,D]
    const float* __restrict__ V, // [B,HKV,S,D]
    float* __restrict__ O,       // [B,H,S,D]
    int B, int H, int HKV, int S, int D,
    int groups,
    float scale
) {
    // block: (b,h,q)
    int qpos = (int)blockIdx.x;
    int h = (int)blockIdx.y;
    int b = (int)blockIdx.z;

    int tid = (int)threadIdx.x; // 0..127
    if (tid >= D) return; // expect D<=128

    int kv_h = h / groups;

    // pointers
    // layout contiguous: (((b*H + h)*S + qpos)*D + d)
    const float* q_ptr = Q + (((b * H + h) * S + qpos) * D);
    const float* k_base = K + (((b * HKV + kv_h) * S) * D);
    const float* v_base = V + (((b * HKV + kv_h) * S) * D);

    float qd = q_ptr[tid];

    __shared__ float red[2];
    __shared__ float sh_expw;
    __shared__ float sh_sumw;

    // Pass 1: find max logit
    float m = -INFINITY;
    for (int j = 0; j <= qpos; ++j) {
        const float* k_ptr = k_base + j * D;
        float prod = qd * k_ptr[tid];
        float dot = block_reduce_sum_128(prod, red);
        float logit = dot * scale;
        // broadcast dot via shared[0]
        m = logit > m ? logit : m;
        __syncthreads();
    }
    // Reduce max across iterations is per-thread identical; m already scalar per thread but computed from broadcasted logit.
    // Still safe.

    // Pass 2: compute sumw and weighted sum of V
    float out_d = 0.0f;
    float sumw = 0.0f;
    for (int j = 0; j <= qpos; ++j) {
        const float* k_ptr = k_base + j * D;
        float prod = qd * k_ptr[tid];
        float dot = block_reduce_sum_128(prod, red);
        float logit = dot * scale;
        float expw;
        if (tid == 0) {
            expw = __expf(logit - m);
            sh_expw = expw;
        }
        __syncthreads();
        expw = sh_expw;
        const float* v_ptr = v_base + j * D;
        out_d += expw * v_ptr[tid];
        if (tid == 0) sumw += expw;
        __syncthreads();
    }
    if (tid == 0) sh_sumw = sumw;
    __syncthreads();
    float inv = 1.0f / sh_sumw;
    O[(((b * H + h) * S + qpos) * D) + tid] = out_d * inv;
}

