    int d = idx % D;
    long long t = idx / D;
    int s = (int)(t % S);
    t /= S;
    int g = (int)(t % groups);
    (void)g; // unused except to select h
    t /= groups;
    int kv_h = (int)(t % HKV);
    int b = (int)(t / HKV);

    // output head index
    int h = kv_h * groups + g;

    long long out_off = (((long long)b * (HKV * groups) + h) * S + s) * D + d;
    long long in_off  = (((long long)b * HKV + kv_h) * S + s) * D + d;
    out[out_off] = inp[in_off];
}

